import APIClient
import ComposableArchitecture
import Foundation
import LogClient

/// The fixed watchlist: each asset's price and 24-hour change, refreshable, opening a detail.
@Reducer
public struct WatchlistFeature {
  @ObservableState
  public struct State: Equatable {
    public var assets: [Asset]
    /// The latest quote per asset id.
    public var quotes: [String: Quote]
    public var isLoading: Bool
    public var loadError: APIError?
    /// When the prices last loaded successfully.
    public var lastUpdated: Date?
    @Presents public var detail: AssetDetailFeature.State?

    public init(
      assets: [Asset] = Asset.watchlist,
      quotes: [String: Quote] = [:],
      isLoading: Bool = false,
      loadError: APIError? = nil,
      lastUpdated: Date? = nil,
      detail: AssetDetailFeature.State? = nil
    ) {
      self.assets = assets
      self.quotes = quotes
      self.isLoading = isLoading
      self.loadError = loadError
      self.lastUpdated = lastUpdated
      self.detail = detail
    }
  }

  public enum Action: Equatable {
    case task
    case refreshPulled
    case retryButtonTapped
    case quotesResponse(Result<[Quote], APIError>)
    case assetTapped(Asset.ID)
    case detail(PresentationAction<AssetDetailFeature.Action>)
  }

  @Dependency(\.apiClient) var apiClient
  @Dependency(\.date.now) var now
  @Dependency(\.logClient) var log

  public init() {}

  public var body: some ReducerOf<Self> {
    Reduce { _, _ in .none }
  }
}
EOF
