import APIClient
import Dependencies

public enum HarnessScenario {
  /// Swaps the API client for a fixed fake when the launch arguments hold
  /// `-harness-scenario <name>`, so UI flows never reach the network. Call it before the root
  /// store is built; with no such argument the app runs live.
  public static func prepare(arguments: [String]) {
    guard let flag = arguments.firstIndex(of: "-harness-scenario"),
      arguments.indices.contains(flag + 1),
      let fake = APIClient.scenario(named: arguments[flag + 1])
    else { return }
    prepareDependencies { $0.apiClient = fake }
  }
}
